@Composable fun RxSelectFriendScreen(onRequest:()->Unit){
    val api=LinkoFriendsApiHolder.api
    var friends by remember{mutableStateOf<List<FriendSearchResult>>(emptyList())}
    var loading by remember{mutableStateOf(true)}
    var message by remember{mutableStateOf<String?>(null)}
    LaunchedEffect(Unit){runCatching{val json=api.friends();val a=json.optJSONArray("friends")?:org.json.JSONArray();friends=buildList{for(i in 0 until a.length()){val o=a.optJSONObject(i)?:continue;add(FriendSearchResult(o.optString("user_id"),o.optString("linko_id"),o.optString("display_name"),o.optString("device_id").takeIf{it.isNotBlank()},o.optString("device_name").takeIf{it.isNotBlank()},o.optBoolean("is_sharing",false)))}}}.onFailure{message=it.message?:"Unable to load friends"};loading=false}
    Column(Modifier.fillMaxSize().padding(16.dp)){Title("Choose a Friend","Real LINKO friends with an active provider device");Spacer(Modifier.height(20.dp));when{loading->LinkoCard{Text("LOADING REAL FRIENDS…",color=TextSub,fontSize=11.sp,fontFamily=JetBrainsMono)};friends.isEmpty()->LinkoCard{Text("NO CONNECTED FRIENDS",color=TextMuted,fontSize=11.sp,fontFamily=JetBrainsMono,fontWeight=FontWeight.Bold);Spacer(Modifier.height(8.dp));Text(message?:"Add a friend and make sure their device is online and sharing.",color=TextSub,fontSize=12.sp,fontFamily=JetBrainsMono)};else->friends.forEach{friend->LinkoCard{Column(Modifier.fillMaxWidth().clickable{val device=friend.deviceId;if(device.isNullOrBlank()){message="This friend has no active provider device."}else{LinkoEngineBridge.connect(device);onRequest()}}){Text(friend.displayName,color=TextPrimary,fontSize=15.sp,fontFamily=JetBrainsMono,fontWeight=FontWeight.Bold);Text(friend.linkoId,color=Blue,fontSize=11.sp,fontFamily=JetBrainsMono);Text(if(friend.isSharing)"SHARING NOW"else"DEVICE OFFLINE",color=if(friend.isSharing)Green else TextMuted,fontSize=10.sp,fontFamily=JetBrainsMono)}};Spacer(Modifier.height(8.dp))}};Spacer(Modifier.weight(1f));PrimaryButton("REFRESH",{loading=true;message=null});Spacer(Modifier.height(24.dp))}
}

