@Composable fun ProviderSharingActiveScreen(onLiveUsage:()->Unit,onStop:()->Unit){val context=LocalContext.current;val auth=remember{LinkoAuth(context)};val identity=remember{LinkoDeviceIdentity()};val shareCode=remember{auth.currentDeviceId()?.takeIf{it.isNotBlank()} ?: identity.deviceFingerprint()};var copied by remember{mutableStateOf(false)};Column(Modifier.fillMaxSize().padding(16.dp),horizontalAlignment=Alignment.CenterHorizontally){Spacer(Modifier.height(8.dp));Title("Sharing Active","Your connection is available to friends");Spacer(Modifier.height(24.dp));Ring(Green,180.dp,pulse=true,label="SHARING");Spacer(Modifier.height(10.dp));Row(verticalAlignment=Alignment.CenterVertically,modifier=Modifier.clip(RoundedCornerShape(12.dp)).background(Surface).border(1.dp,Border,RoundedCornerShape(12.dp)).padding(start=12.dp)){Column(Modifier.weight(1f)){Text("FRIENDS CAN ENTER THIS ID TO CONNECT",color=TextSub,fontSize=9.sp,fontFamily=JetBrainsMono);Text(shareCode,color=Green,fontSize=17.sp,fontFamily=JetBrainsMono,fontWeight=FontWeight.Bold)};IconButton(onClick={val cb=context.getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager;cb.setPrimaryClip(ClipData.newPlainText("LINKO device ID",shareCode));copied=true}){Icon(Icons.Filled.ContentCopy,"Copy ID",tint=Green)}};if(copied)Text("COPIED",color=Green,fontSize=9.sp,fontFamily=JetBrainsMono);Spacer(Modifier.height(18.dp));LinkoCard{InfoRow("STATUS","WAITING","No active connection",Green)};Spacer(Modifier.weight(1f));PrimaryButton("LIVE USAGE",onLiveUsage,outline=true);Spacer(Modifier.height(8.dp));PrimaryButton("STOP SHARING",onStop,color=Red);Spacer(Modifier.height(24.dp))}}
